SINA_SMART["immuno1-antigens"] = {"lecture":"immuno1-antigens","title":"Antigens","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-antigens:e0","text":"Immunity: tolerate self, reject non-self.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e1","text":"Antigen: induces a response and reacts specifically with its products.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e2","text":"Antigenicity (recognition) vs immunogenicity (triggering a response).","topic":"Antigenicity and immunogenicity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e3","text":"All immunogens are antigens; not all antigens are immunogens.","topic":"Antigenicity and immunogenicity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e4","text":"Immunogenicity: foreignness, size > 3-5 kDa, rigidity, complexity.","topic":"Antigenicity and immunogenicity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e5","text":"Proteins > carbohydrates > lipids > nucleic acids.","topic":"Antigenicity and immunogenicity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e6","text":"Dose: ng tolerance; µg high affinity; very high paralysis.","topic":"Antigenicity and immunogenicity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e7","text":"Epitope binds paratope; linear vs conformational.","topic":"Epitopes and haptens","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e8","text":"B cells see native antigen; T cells see peptide + MHC.","topic":"Epitopes and haptens","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e9","text":"Hapten + carrier → immunogenic.","topic":"Epitopes and haptens","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e10","text":"Superantigens: polyclonal T activation, cytokine storm.","topic":"Superantigens and natural antigens","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-antigens:e11","text":"Allo-, xeno-, autoantigens; Bombay phenotype.","topic":"Superantigens and natural antigens","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"7agq6q":"a","3bzrqf":"a","c2uizh":"a","4xh3aq":"a","v126qw":"a","61zpkk":"a","xqnoh0":"a","5jjurq":"a","vug2d2":"a","13qrs20":"a","huhzxt":"a","1s5vfpm":"a","n04toa":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-antigens:e0":{"s":0,"u":["Immunity: tolerate self, reject non-self.","Immunity is the set of mechanisms by which an organism recognises and tolerates self and recognises and rejects non-self (foreign substances, infectious agents, modified self); it can be innate or adaptive, active or passive."],"dp":[]},"immuno1-antigens:e1":{"s":0,"u":["Antigen: induces a response and reacts specifically with its products.","An antigen ('antibody generator') is any natural, artificial or synthetic molecule able to induce an immune response and to react specifically with its products (antibodies, BCR, TCR)."],"dp":[]},"immuno1-antigens:e2":{"s":1,"u":["Antigenicity (recognition) vs immunogenicity (triggering a response).","Immunogenicity : triggering a T and/or B response in vivo.","Antigenicity : being recognised by immune effectors (in vivo and in vitro)."],"dp":[]},"immuno1-antigens:e3":{"s":1,"u":["All immunogens are antigens; not all antigens are immunogens.","All immunogens are antigens, but not all antigens are immunogens."],"dp":[]},"immuno1-antigens:e4":{"s":1,"u":["Immunogenicity: foreignness, size > 3-5 kDa, rigidity, complexity.","Immunogenicity : triggering a T and/or B response in vivo.","Factors: taxonomic distance ('foreignness': chicken albumin is strongly immunogenic in humans, human albumin not at all); molecular weight (cutoff about 3-5 kDa ); rigidity , mobility and complexity (e.g. glycosylation); chemical nature: proteins > carbohydrates > lipids > nucleic acids (pure DNA is not immunogenic experimentally; lipids may act as haptens); host genetics (immune response genes in the MHC class II region); dose (ng: low-dose tolerance; µg: few but high-affinity antibodies; mg: response rises with dose; very high: immune paralysis) and route."],"dp":[]},"immuno1-antigens:e5":{"s":1,"u":["Proteins > carbohydrates > lipids > nucleic acids.","Factors: taxonomic distance ('foreignness': chicken albumin is strongly immunogenic in humans, human albumin not at all); molecular weight (cutoff about 3-5 kDa ); rigidity , mobility and complexity (e.g. glycosylation); chemical nature: proteins > carbohydrates > lipids > nucleic acids (pure DNA is not immunogenic experimentally; lipids may act as haptens); host genetics (immune response genes in the MHC class II region); dose (ng: low-dose tolerance; µg: few but high-affinity antibodies; mg: response rises with dose; very high: immune paralysis) and route."],"dp":[]},"immuno1-antigens:e6":{"s":1,"u":["Dose: ng tolerance; µg high affinity; very high paralysis.","Factors: taxonomic distance ('foreignness': chicken albumin is strongly immunogenic in humans, human albumin not at all); molecular weight (cutoff about 3-5 kDa ); rigidity , mobility and complexity (e.g. glycosylation); chemical nature: proteins > carbohydrates > lipids > nucleic acids (pure DNA is not immunogenic experimentally; lipids may act as haptens); host genetics (immune response genes in the MHC class II region); dose (ng: low-dose tolerance; µg: few but high-affinity antibodies; mg: response rises with dose; very high: immune paralysis) and route."],"dp":[]},"immuno1-antigens:e7":{"s":2,"u":["Epitope binds paratope; linear vs conformational.","Linear (continuous) epitopes are consecutive amino acids; most protein epitopes are conformational (discontinuous) , formed by folding and lost on denaturation.","An epitope (antigenic determinant) is the active part binding the complementary paratope ; an antigen is a mosaic of epitopes , and the same epitope can occur on different antigens (cross-reaction)."],"dp":[]},"immuno1-antigens:e8":{"s":2,"u":["B cells see native antigen; T cells see peptide + MHC.","B cells recognise native antigen with membrane immunoglobulin; T cells only recognise peptides presented by MHC on antigen-presenting cells."],"dp":[]},"immuno1-antigens:e9":{"s":2,"u":["Hapten + carrier → immunogenic.","A hapten is a small molecule with one epitope, antigenic but not immunogenic ; coupled to a carrier protein it induces anti-hapten and anti-carrier antibodies."],"dp":[{"h":"Why some drugs cause allergy although they are tiny","t":"Drugs like penicillin are far too small to be immunogenic on their own; they act as haptens. Once they bind covalently to the patient's own proteins, the hapten-carrier complex is seen as foreign and can trigger antibodies, including IgE. That is how a small molecule can cause a serious allergic reaction. Source: the lecture's hapten and carrier concept."}]},"immuno1-antigens:e10":{"s":3,"u":["Superantigens: polyclonal T activation, cytokine storm."],"dp":[]},"immuno1-antigens:e11":{"s":3,"u":["Allo-, xeno-, autoantigens; Bombay phenotype.","ABO; the Bombay (Oh) phenotype lacks H antigen and has anti-H antibodies), xenoantigens (between species), autoantigens (self)."],"dp":[]}},"meta":{"7agq6q":{"a":"recall","vg":"immuno1-antigens:e0/recall/1"},"3bzrqf":{"a":"recall","vg":"immuno1-antigens:e2/recall/1"},"c2uizh":{"a":"recall","vg":"immuno1-antigens:e3/recall/1"},"4xh3aq":{"a":"recall","vg":"immuno1-antigens:e4/recall/1"},"v126qw":{"a":"recall","vg":"immuno1-antigens:e4/recall/2"},"61zpkk":{"a":"recall","vg":"immuno1-antigens:e6/recall/1"},"xqnoh0":{"a":"recall","vg":"immuno1-antigens:e7/recall/1"},"5jjurq":{"a":"recall","vg":"immuno1-antigens:e7/recall/2"},"vug2d2":{"a":"recall","vg":"immuno1-antigens:e8/recall/1"},"13qrs20":{"a":"recall","vg":"immuno1-antigens:e9/recall/1"},"huhzxt":{"a":"recall","vg":"immuno1-antigens:e10/recall/1"},"1s5vfpm":{"a":"recall","vg":"immuno1-antigens:e3/recall/2"},"n04toa":{"a":"recall","vg":"immuno1-antigens:e11/recall/1"}},"explRev":"18e48b29d4a2"};
